base.css:
.cloze-panel {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  background: var(--surface);
}

workingTree.css:
.cloze-panel {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  background: var(--surface);
}

.cloze-line {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: calc(1.05rem * var(--font-scale));
  line-height: 2.4;
}

base.css:
.cloze-select {
  display: inline-block;
  width: auto;
  min-width: 10rem;
  margin: 0 0.25rem;
  padding-block: 0.4rem;
  vertical-align: baseline;
}

.cloze-token {
  display: inline-flex;
  align-items: center;
  min-height: 2rem;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  margin: 0 0.25rem;
  padding: 0.2rem 0.55rem;
  color: var(--text);
  background: var(--surface-muted);
  font-weight: 800;
  vertical-align: baseline;
}

workingTree.css:
.cloze-token {
  display: inline-block;
  max-width: calc(100% - 0.5rem);
  min-height: 2rem;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  margin: 0 0.25rem;
  padding: 0.2rem 0.55rem;
  color: var(--text);
  background: var(--surface-muted);
  font-weight: 800;
  vertical-align: baseline;
}

.cloze-choice {
  display: inline-grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: min(10rem, calc(100% - 0.5rem));
  max-width: calc(100% - 0.5rem);
  margin: 0 0.25rem;
  vertical-align: baseline;
}
